tool_schemas.implementation:
def Optional_Settings(action, session_token=None, operator_id=None, session_id=None, server_id=None, credential_id=None, email=None, password=None, limit=None, cursor=None, sort=None, status=None, credential_type=None, server=None, credential=None, **_extra):
    import json, os, datetime, time, re, hashlib, secrets, base64, hmac

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0240000" if __import__("os").path.isdir("./environment_mix/0240000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(endpoint, status, credential=None, operator=None, session=None, error_code=None, message=None):
        # Best-effort request log used for observable dynamics; create file if missing.
        try:
            logs = _load("request_logs.json")
            logs = _ensure_list(logs)
            dt = _now()
            logs.append({
                "id": "mcp_req_" + secrets.token_urlsafe(10),
                "endpoint": endpoint,
                "action": action,
                "status": status,
                "error_code": error_code,
                "message": message,
                "credential_id": credential,
                "operator_id": operator,
                "session_id": session,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                "timestamp": _iso(dt),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limit_check():
        # Simple fixed-window guard derived from request_logs.json if present.
        # 120 requests/minute globally; refuse with RATE_LIMIT when exceeded.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            now = _now()
            cutoff = now - datetime.timedelta(seconds=60)
            c = 0
            for r in logs[-2000:]:
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= 120:
                return _err("RATE_LIMIT", "Too many requests. Please retry later.", retry_after_seconds=60)
        except Exception:
            return None
        return None

    def _hash_session_token(token):
        # Stored session_token_hash is a hash of the bearer; accept either:
        # - exact hash passed in (common in local setups)
        # - raw token passed in, we hash it
        if not isinstance(token, str) or not token:
            return None, None
        presented = token.strip()
        if re.fullmatch(r"[a-fA-F0-9]{64}", presented):
            return presented.lower(), "hash"
        if presented.startswith("sha256$"):
            maybe = presented.split("$", 1)[1]
            if re.fullmatch(r"[a-fA-F0-9]{64}", maybe):
                return maybe.lower(), "sha256$hash"
        # raw token -> hash hex
        return hashlib.sha256(presented.encode("utf-8")).hexdigest(), "raw"

    def _verify_password(stored_hash, pw):
        # IMPORTANT: do NOT compare pw to stored_hash; stored_hash is hash.
        # Accept if pw verifies for common formats present in JSON stores.
        if not isinstance(stored_hash, str) or not isinstance(pw, str):
            return False
        sh = stored_hash.strip()
        p = pw

        # If store uses "plain$<pw>" for dev (discouraged but possible)
        if sh.startswith("plain$"):
            return hmac.compare_digest(sh[6:], p)

        # pbkdf2_sha256$iters$salt_b64$dk_b64
        if sh.startswith("pbkdf2_sha256$"):
            parts = sh.split("$")
            if len(parts) == 4:
                try:
                    iters = int(parts[1])
                    salt = base64.urlsafe_b64decode(parts[2] + "==")
                    dk = base64.urlsafe_b64decode(parts[3] + "==")
                    calc = hashlib.pbkdf2_hmac("sha256", p.encode("utf-8"), salt, iters, dklen=len(dk))
                    return hmac.compare_digest(calc, dk)
                except Exception:
                    return False

        # argon2id style: $argon2id$v=19$m=...,t=...,p=...$salt_b64$hash_b64
        if sh.startswith("$argon2id$"):
            # Standard library cannot compute Argon2; accept a self-hosted compatibility
            # where caller provides the already-hashed value exactly matching stored hash.
            return hmac.compare_digest(sh, p)

        # bcrypt $2...
        if sh.startswith("$2a$") or sh.startswith("$2b$") or sh.startswith("$2y$"):
            # stdlib cannot compute bcrypt; same compatibility as above
            return hmac.compare_digest(sh, p)

        # Fallback: exact match (for systems that pass pre-hashed secret)
        return hmac.compare_digest(sh, p)

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = secrets.token_bytes(16)
        n = int.from_bytes(raw, "big")
        out = []
        while n > 0:
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        s = "".join(reversed(out)) or "0"
        if len(s) < 18:
            s = (alphabet[0] * (18 - len(s))) + s
        return f"{prefix}{s}"

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _sort_key(field, val):
        if field in ("created_at", "updated_at", "issued_at", "expires_at", "last_seen_at", "last_healthcheck_at", "last_login_at"):
            dt = _parse_dt(val)
            return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if val is None:
            return ""
        return str(val).lower()

    def _paginate(rows, sort_spec, limit, cursor_val):
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return None, _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        if sort_spec is None:
            sort_spec = "created_at"
        if not isinstance(sort_spec, str):
            return None, _err("VALIDATION_ERROR", "sort must be a string.")
        desc = sort_spec.startswith("-")
        field = sort_spec[1:] if desc else sort_spec
        rows2 = list(rows)
        rows2.sort(key=lambda r: _sort_key(field, r.get(field)), reverse=desc)

        start = 0
        if cursor_val:
            cobj = _decode_cursor(cursor_val)
            if cobj and cobj.get("after") is not None:
                after = cobj.get("after")
                # cursor is last seen primary id; find it
                for i, r in enumerate(rows2):
                    if r.get("id") == after:
                        start = i + 1
                        break

        page = rows2[start:start + limit]
        has_more = start + limit < len(rows2)
        next_cursor = _encode_cursor({"after": page[-1]["id"]}) if (has_more and page) else None
        return {
            "items": page,
            "total": len(rows2),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort_spec,
        }, None

    def _auth_session(required=True):
        # Authenticate via session_token; mark expired if past expiry.
        if not isinstance(session_token, str) or not session_token.strip():
            if required:
                return None, None, _err("VALIDATION_ERROR", "session_token must be a non-empty string.")
            return None, None, None
        sess_hash, _mode = _hash_session_token(session_token)
        if not sess_hash:
            return None, None, _err("VALIDATION_ERROR", "session_token is invalid.")
        sessions = _ensure_list(_load("sessions.json"))
        operators = _ensure_list(_load("operators.json"))
        now = _now()

        sess = None
        for s in sessions:
            if s.get("session_token_hash") == sess_hash:
                sess = s
                break
        if not sess:
            return None, None, _err("UNAUTHORIZED", "Session not found.")
        # expire if needed
        exp = _parse_dt(sess.get("expires_at"))
        if exp and now >= exp and sess.get("status") == "active":
            # transition active -> expired allowed
            sess["status"] = "expired"
            sess["updated_at"] = _iso(now)
            sess["last_seen_at"] = _iso(now)
            _save("sessions.json", sessions)
        # validate status
        if sess.get("status") != "active":
            return sess, None, _err("UNAUTHORIZED", "Session is not active.", session_status=sess.get("status"))
        if exp and now >= exp:
            return sess, None, _err("UNAUTHORIZED", "Session expired.")
        # update last_seen_at
        sess["last_seen_at"] = _iso(now)
        sess["updated_at"] = _iso(now)
        _save("sessions.json", sessions)

        op = None
        for o in operators:
            if o.get("id") == sess.get("operator_id"):
                op = o
                break
        if not op:
            return sess, None, _err("UNAUTHORIZED", "Operator not found for session.")
        if op.get("status") != "active":
            return sess, op, _err("UNAUTHORIZED", "Operator is not active.", operator_status=op.get("status"))
        return sess, op, None

    # basic validation for action
    if not isinstance(action, str) or not action:
        _log("Optional_Settings", "error", error_code="VALIDATION_ERROR", message="Missing action")
        return _err("VALIDATION_ERROR", "action must be provided.")

    rl = _rate_limit_check()
    if rl:
        _log("Optional_Settings", "error", error_code=rl["error"]["code"], message=rl["error"]["message"])
        return rl

    endpoint = "Optional_Settings"

    try:
        # ---- SIGN IN ----
        if action == "sign_in":
            if not isinstance(email, str) or not email.strip():
                _log(endpoint, "error", error_code="VALIDATION_ERROR", message="email required")
                return _err("VALIDATION_ERROR", "email must be a non-empty string.")
            if not isinstance(password, str) or not password:
                _log(endpoint, "error", error_code="VALIDATION_ERROR", message="password required")
                return _err("VALIDATION_ERROR", "password must be a non-empty string.")

            operators = _ensure_list(_load("operators.json"))
            sessions = _ensure_list(_load("sessions.json"))

            op = None
            for o in operators:
                if isinstance(o.get("email"), str) and o["email"].lower() == email.strip().lower():
                    op = o
                    break
            if not op:
                _log(endpoint, "error", error_code="UNAUTHORIZED", message="Invalid credentials")
                return _err("UNAUTHORIZED", "Invalid email or password.")

            # no sessions if disabled/locked
            if op.get("status") != "active":
                _log(endpoint, "error", operator=op.get("id"), error_code="UNAUTHORIZED", message="Operator not active")
                return _err("UNAUTHORIZED", "Operator is not active.", operator_status=op.get("status"))

            if not _verify_password(op.get("password_hash"), password):
                # increment failed_login_count; lock at 10
                now = _now()
                try:
                    op["failed_login_count"] = int(op.get("failed_login_count") or 0) + 1
                except Exception:
                    op["failed_login_count"] = 1
                # transition to locked if reaches 10
                if op["failed_login_count"] >= 10 and op.get("status") == "active":
                    op["status"] = "locked"
                op["updated_at"] = _iso(now)
                _save("operators.json", operators)
                _log(endpoint, "error", operator=op.get("id"), error_code="UNAUTHORIZED", message="Invalid credentials")
                return _err("UNAUTHORIZED", "Invalid email or password.")

            # success: reset failed count, update last_login_at, create active session
            now = _now()
            op["failed_login_count"] = 0
            op["last_login_at"] = _iso(now)
            op["updated_at"] = _iso(now)
            _save("operators.json", operators)

            # if client provided session_token, store its hash; else generate a random token and return it
            issued_token = session_token if (isinstance(session_token, str) and session_token.strip()) else ("st_" + secrets.token_urlsafe(24))
            sess_hash, _m = _hash_session_token(issued_token)

            # unique(session_token_hash)
            for s in sessions:
                if s.get("session_token_hash") == sess_hash:
                    # idempotent: if existing is active and not expired, return it; else conflict
                    exp = _parse_dt(s.get("expires_at"))
                    if s.get("status") == "active" and (not exp or _now() < exp):
                        _log(endpoint, "ok", operator=op.get("id"), session=s.get("id"))
                        return {
                            "session": {
                                "id": s.get("id"),
                                "operator_id": s.get("operator_id"),
                                "status": s.get("status"),
                                "issued_at": s.get("issued_at"),
                                "expires_at": s.get("expires_at"),
                                "last_seen_at": s.get("last_seen_at"),
                                "created_at": s.get("created_at"),
                                "updated_at": s.get("updated_at"),
                            },
                            "session_token": issued_token,
                        }
                    _log(endpoint, "error", operator=op.get("id"), error_code="CONFLICT", message="session_token already used")
                    return _err("CONFLICT", "session_token is already in use; provide a different token.")

            sid = _b32_id("mcp_sess_")
            expires = now + datetime.timedelta(days=7)
            row = {
                "id": sid,
                "operator_id": op["id"],
                "session_token_hash": sess_hash,
                "status": "active",
                "issued_at": _iso(now),
                "expires_at": _iso(expires),
                "last_seen_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            sessions.append(row)
            _save("sessions.json", sessions)
            _log(endpoint, "ok", operator=op.get("id"), session=sid)
            return {
                "session": {
                    "id": row["id"],
                    "operator_id": row["operator_id"],
                    "status": row["status"],
                    "issued_at": row["issued_at"],
                    "expires_at": row["expires_at"],
                    "last_seen_at": row["last_seen_at"],
                    "created_at": row["created_at"],
                    "updated_at": row["updated_at"],
                },
                "session_token": issued_token,
            }

        # ---- SIGN OUT ----
        if action == "sign_out":
            sess, op, e = _auth_session(required=True)
            if e:
                _log(endpoint, "error", error_code=e["error"]["code"], message=e["error"]["message"], session=sess.get("id") if sess else None, operator=op.get("id") if op else None)
                return e
            sessions = _ensure_list(_load("sessions.json"))
            now = _now()
            changed = False
            for s in sessions:
                if s.get("id") == sess.get("id"):
                    if s.get("status") == "active":
                        s["status"] = "revoked"
                        s["updated_at"] = _iso(now)
                        s["last_seen_at"] = _iso(now)
                        changed = True
                    break
            if not changed:
                _log(endpoint, "error", operator=op.get("id"), session=sess.get("id"), error_code="INVALID_TRANSITION", message="Session not active")
                return _err("INVALID_TRANSITION", "Session is not active; cannot revoke.", session_status=sess.get("status"))
            _save("sessions.json", sessions)
            _log(endpoint, "ok", operator=op.get("id"), session=sess.get("id"))
            return {
                "session": {
                    "id": sess.get("id"),
                    "operator_id": sess.get("operator_id"),
                    "status": "revoked",
                    "issued_at": sess.get("issued_at"),
                    "expires_at": sess.get("expires_at"),
                    "last_seen_at": _iso(now),
                    "created_at": sess.get("created_at"),
                    "updated_at": _iso(now),
                }
            }

        # ---- GET SESSION ----
        if action == "get_session":
            sess, op, e = _auth_session(required=True)
            if e:
                _log(endpoint, "error", error_code=e["error"]["code"], message=e["error"]["message"], session=sess.get("id") if sess else None, operator=op.get("id") if op else None)
                return e
            _log(endpoint, "ok", operator=op.get("id"), session=sess.get("id"))
            return {
                "session": {
                    "id": sess.get("id"),
                    "operator_id": sess.get("operator_id"),
                    "status": sess.get("status"),
                    "issued_at": sess.get("issued_at"),
                    "expires_at": sess.get("expires_at"),
                    "last_seen_at": sess.get("last_seen_at"),
                    "created_at": sess.get("created_at"),
                    "updated_at": sess.get("updated_at"),
                }
            }

        # ---- SERVER LIST/GET/CREATE/UPDATE/DELETE and CREDENTIAL ops are supported but require auth ----
        sess, op, e = _auth_session(required=True)
        if e:
            _log(endpoint, "error", error_code=e["error"]["code"], message=e["error"]["message"], session=sess.get("id") if sess else None, operator=op.get("id") if op else None)
            return e

        is_adminish = op.get("role") in ("owner", "admin")

        if action == "list_servers":
            servers = _ensure_list(_load("supabase_servers.json"))
            # viewers can list
            rows = []
            for r in servers:
                if status and r.get("status") != status:
                    continue
                rows.append(r)
            # sort enum for this tool
            allowed = {"created_at","-created_at","updated_at","-updated_at","name","-name","last_healthcheck_at","-last_healthcheck_at"}
            if sort is not None and sort not in allowed:
                _log(endpoint, "error", operator=op.get("id"), error_code="VALIDATION_ERROR", message="Invalid sort")
                return _err("VALIDATION_ERROR", "Invalid sort value.")
            page, pe = _paginate(rows, sort or "created_at", limit, cursor)
            if pe:
                _log(endpoint, "error", operator=op.get("id"), error_code=pe["error"]["code"], message=pe["error"]["message"])
                return pe
            _log(endpoint, "ok", operator=op.get("id"), session=sess.get("id"))
            return page

        if action == "get_server":
            if not isinstance(server_id, str) or not re.match(r"^mcp_srv_[0-9A-HJKMNP-TV-Z]{18,}$", server_id):
                _log(endpoint, "error", operator=op.get("id"), error_code="VALIDATION_ERROR", message="server_id invalid")
                return _err("VALIDATION_ERROR", "server_id is required and must be a valid mcp_srv_ id.")
            servers = _ensure_list(_load("supabase_servers.json"))
            for r in servers:
                if r.get("id") == server_id:
                    _log(endpoint, "ok", operator=op.get("id"), session=sess.get("id"))
                    return {"server": r}
            _log(endpoint, "error", operator=op.get("id"), error_code="NOT_FOUND", message="server not found")
            return _err("NOT_FOUND", "Server not found.")

        if action == "create_server":
            if not is_adminish:
                _log(endpoint, "error", operator=op.get("id"), error_code="UNAUTHORIZED", message="viewer read-only")
                return _err("UNAUTHORIZED", "Insufficient role to create servers.")
            if not isinstance(server, dict):
                _log(endpoint, "error", operator=op.get("id"), error_code="VALIDATION_ERROR", message="server object required")
                return _err("VALIDATION_ERROR", "server must be provided.")
            name = server.get("name")
            base_url = server.get("base_url")
            owner_id = server.get("owner_operator_id") or op.get("id")
            if not isinstance(name, str) or not name.strip():
                return _err("VALIDATION_ERROR", "server.name must be a non-empty string.")
            if not isinstance(base_url, str) or not base_url.startswith("http"):
                return _err("VALIDATION_ERROR", "server.base_url must start with 'http'.")
            if not isinstance(owner_id, str) or not re.match(r"^mcp_opr_[0-9A-HJKMNP-TV-Z]{18,}$", owner_id):
                return _err("VALIDATION_ERROR", "server.owner_operator_id must be a valid operator id.")
            servers = _ensure_list(_load("supabase_servers.json"))
            # unique(owner_operator_id, name)
            for r in servers:
                if r.get("owner_operator_id") == owner_id and isinstance(r.get("name"), str) and r["name"].lower() == name.strip().lower() and r.get("status") != "deleted":
                    return _err("CONFLICT", "Server name already exists for this owner.")
            now = _now()
            rid = _b32_id("mcp_srv_")
            row = {
                "id": rid,
                "name": name.strip(),
                "base_url": base_url.strip(),
                "project_ref": server.get("project_ref"),
                "owner_operator_id": owner_id,
                "status": server.get("status") or "active",
                "notes": server.get("notes"),
                "last_healthcheck_at": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            if row["status"] not in ("active", "disabled", "deleted"):
                return _err("VALIDATION_ERROR", "server.status is invalid.")
            servers.append(row)
            _save("supabase_servers.json", servers)
            _log(endpoint, "ok", operator=op.get("id"), session=sess.get("id"))
            return {"server": row}

        if action == "update_server":
            if not is_adminish:
                return _err("UNAUTHORIZED", "Insufficient role to update servers.")
            if not isinstance(server_id, str) or not re.match(r"^mcp_srv_[0-9A-HJKMNP-TV-Z]{18,}$", server_id):
                return _err("VALIDATION_ERROR", "server_id is required and must be a valid mcp_srv_ id.")
            if not isinstance(server, dict):
                return _err("VALIDATION_ERROR", "server must be provided.")
            servers = _ensure_list(_load("supabase_servers.json"))
            target = None
            for r in servers:
                if r.get("id") == server_id:
                    target = r
                    break
            if not target:
                return _err("NOT_FOUND", "Server not found.")
            now = _now()
            # enforce unique name per owner on rename
            if "name" in server and server.get("name") is not None:
                nm = server.get("name")
                if not isinstance(nm, str) or not nm.strip():
                    return _err("VALIDATION_ERROR", "server.name must be a non-empty string.")
                owner_id = target.get("owner_operator_id")
                for r in servers:
                    if r.get("id") != target.get("id") and r.get("owner_operator_id") == owner_id and isinstance(r.get("name"), str) and r["name"].lower() == nm.strip().lower() and r.get("status") != "deleted":
                        return _err("CONFLICT", "Server name already exists for this owner.")
                target["name"] = nm.strip()
            if "base_url" in server and server.get("base_url") is not None:
                bu = server.get("base_url")
                if not isinstance(bu, str) or not bu.startswith("http"):
                    return _err("VALIDATION_ERROR", "server.base_url must start with 'http'.")
                target["base_url"] = bu.strip()
            if "project_ref" in server:
                target["project_ref"] = server.get("project_ref")
            if "notes" in server:
                target["notes"] = server.get("notes")
            if "status" in server and server.get("status") is not None:
                ns = server.get("status")
                if ns not in ("active", "disabled", "deleted"):
                    return _err("VALIDATION_ERROR", "server.status is invalid.")
                # lifecycle transitions
                cur = target.get("status")
                allowed = {"active": {"disabled", "deleted"}, "disabled": {"active", "deleted"}, "deleted": set()}
                if ns != cur and ns not in allowed.get(cur, set()):
