            kid = "local_kid_01"
            ciphertext = "enc$" + base64.urlsafe_b64encode(hashlib.sha256(secret.encode("utf-8")).digest()).decode("ascii").rstrip("=")
            if not ciphertext or not kid:
                return _err("VALIDATION_ERROR", "secret_ciphertext and secret_kid must be non-empty.")
            creds = _ensure_list(_load("server_credentials.json"))
            now = _now()
            # rotate any previous active
