            _log(endpoint, "ok", operator=op.get("id"), session=sess.get("id"))
            return {"credential": {k: target.get(k) for k in ("id","server_id","credential_type","status","secret_kid","last_rotated_at","created_at","updated_at")}}

        if action == "revoke_server_credential":
            if not is_adminish:
                return _err("UNAUTHORIZED", "Insufficient role to manage credentials.")
            if not isinstance(credential_id, str) or not re.match(r"^mcp_cred_[0-9A-HJKMNP-TV-Z]{18,}$", credential_id):
                return _err("VALIDATION_ERROR", "credential_id is required and must be a valid mcp_cred_ id.")
            creds = _ensure_list(_load("server_credentials.json"))
            now = _now()
            target = None
            for c in creds:
                if c.get("id") == credential_id:
                    target = c
                    break
            if not target:
                return _err("NOT_FOUND", "Credential not found.")
            if target.get("status") == "revoked":
