                _log(endpoint, "ok", operator=op.get("id"), session=sess.get("id"))
                return {"credential": {k: target.get(k) for k in ("id","server_id","credential_type","status","secret_kid","last_rotated_at","created_at","updated_at")}}
            if target.get("status") not in ("active","rotated"):
                return _err("INVALID_TRANSITION", f"Cannot revoke credential from status {target.get('status')}.")
            target["status"] = "revoked"
            target["updated_at"] = _iso(now)
            _save("server_credentials.json", creds)
            _log(endpoint, "ok", operator=op.get("id"), session=sess.get("id"))
            return {"credential": {k: target.get(k) for k in ("id","server_id","credential_type","status","secret_kid","last_rotated_at","created_at","updated_at")}}

        _log(endpoint, "error", operator=op.get("id"), session=sess.get("id"), error_code="VALIDATION_ERROR", message="Unknown action")
        return _err("VALIDATION_ERROR", "Unknown action.")
    except Exception as ex:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", message=str(ex))
        return _err("VALIDATION_ERROR", "Request could not be processed.", detail=str(ex))

