        _log("error", error_code="VALIDATION_ERROR", message="Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

    allowed_sort = {"created_at","-created_at","updated_at","-updated_at","email","-email","display_name","-display_name","last_login_at","-last_login_at"}
    if sort is None:
        sort = "created_at"
    if sort not in allowed_sort:
        _log("error", error_code="VALIDATION_ERROR", message="Invalid sort")
        return _err("VALIDATION_ERROR", "Invalid sort value.")
    if status is not None and status not in ("active","disabled","locked"):
        _log("error", error_code="VALIDATION_ERROR", message="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status filter.")
