        _log("error", error_code="VALIDATION_ERROR", message="Invalid role")
        return _err("VALIDATION_ERROR", "Invalid role filter.")
    if email is not None and (not isinstance(email, str) or not email.strip()):
        _log("error", error_code="VALIDATION_ERROR", message="Invalid email")
        return _err("VALIDATION_ERROR", "email filter must be a non-empty string when provided.")

    sessions = _load("sessions.json")
    operators = _load("operators.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(operators, list):
        operators = []

    now = _now()
    sh = _hash_session_token(session_token)
    sess = None
    for s in sessions:
        if s.get("session_token_hash") == sh:
            sess = s
            break
    if not sess:
        _log("error", error_code="UNAUTHORIZED", message="Session not found")
        return _err("UNAUTHORIZED", "Session not found.")
    exp = _parse_dt(sess.get("expires_at"))
    if exp and now >= exp and sess.get("status") == "active":
        sess["status"] = "expired"
        sess["updated_at"] = _iso(now)
        sess["last_seen_at"] = _iso(now)
        _save("sessions.json", sessions)
    if sess.get("status") != "active" or (exp and now >= exp):
        _log("error", session_id=sess.get("id"), operator_id=sess.get("operator_id"), error_code="UNAUTHORIZED", message="Session invalid")
        return _err("UNAUTHORIZED", "Session is invalid.", session_status=sess.get("status"))

    caller = None
    for o in operators:
        if o.get("id") == sess.get("operator_id"):
            caller = o
            break
    if not caller or caller.get("status") != "active":
        _log("error", session_id=sess.get("id"), operator_id=sess.get("operator_id"), error_code="UNAUTHORIZED", message="Operator not active")
        return _err("UNAUTHORIZED", "Operator is not active.")
    if caller.get("role") not in ("owner","admin"):
        _log("error", operator_id=caller.get("id"), session_id=sess.get("id"), error_code="UNAUTHORIZED", message="Insufficient role")
        return _err("UNAUTHORIZED", "Insufficient role to list operators.")

    # update last_seen
    sess["last_seen_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    _save("sessions.json", sessions)

    rows = []
    for o in operators:
        if status and o.get("status") != status:
            continue
        if role and o.get("role") != role:
            continue
        if email and (o.get("email") or "").lower() != email.strip().lower():
            continue
        rows.append({
            "id": o.get("id"),
            "email": o.get("email"),
            "display_name": o.get("display_name"),
            "role": o.get("role"),
            "status": o.get("status"),
            "last_login_at": o.get("last_login_at"),
            "failed_login_count": o.get("failed_login_count"),
            "created_at": o.get("created_at"),
            "updated_at": o.get("updated_at"),
        })

    desc = sort.startswith("-")
    field = sort[1:] if desc else sort

    def _key(r):
        if field in ("created_at","updated_at","last_login_at"):
            return _parse_dt(r.get(field)) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        v = r.get(field)
        return "" if v is None else str(v).lower()

    rows.sort(key=_key, reverse=desc)

    start = 0
    if cursor:
        cobj = _decode_cursor(cursor)
        if cobj and cobj.get("after"):
            after = cobj["after"]
            for i, r in enumerate(rows):
                if r.get("id") == after:
                    start = i + 1
                    break

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = _encode_cursor({"after": page[-1]["id"]}) if has_more and page else None

    _log("ok", operator_id=caller.get("id"), session_id=sess.get("id"))
    return {"items": page, "total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "sort": sort}

