        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(logs, status, actor_operator_id=None, session_id=None, error_code=None, message=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "mcp_req_" + secrets.token_urlsafe(10),
            "endpoint": "Optional_Settings__create_operator",
            "action": action,
            "status": status,
            "actor_operator_id": actor_operator_id,
            "session_id": session_id,
            "error_code": error_code,
            "message": message,
            "latency_ms": latency_ms,
            "created_at": now.isoformat()
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        # deterministic-ish prefix style used in store; uniqueness sufficient for local JSON
        return f"{prefix}_{secrets.token_urlsafe(18)}"

    def _looks_like_email(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if len(s) < 3 or len(s) > 320:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s) is not None

    def _hash_session_token(presented):
        # sessions store session_token_hash; never compare presented token to stored hash ciphertext
        if not isinstance(presented, str) or not presented.strip():
            return None
        presented = presented.strip()
        if presented.startswith("sha256$"):
            # caller already provided a hashed token string
            return presented
        # otherwise hash into the service format
        h = hashlib.sha256(presented.encode("utf-8")).hexdigest()
        return "sha256$" + h

    def _sanitize_operator_row(row):
        if not isinstance(row, dict):
            return row
        out = dict(row)
        # never return password_hash
        out.pop("password_hash", None)
        return out

    logs = _ensure_logs()
    actor_operator_id = None
    session_id = None

    # ---- Validate inputs ----
    if action != "create_operator":
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="Invalid action.")
        return _err("VALIDATION_ERROR", "Invalid action.", allowed=["create_operator"])
    if not isinstance(session_token, str) or not session_token.strip():
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="session_token is required.")
        return _err("VALIDATION_ERROR", "session_token is required and must be a non-empty string.")
    if not isinstance(operator, dict):
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="operator must be an object.")
        return _err("VALIDATION_ERROR", "operator must be an object.")

    email = operator.get("email")
    password = operator.get("password")
    display_name = operator.get("display_name")
    role = operator.get("role")
    status = operator.get("status", "active")

    if not _looks_like_email(email):
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="Invalid email.")
        return _err("VALIDATION_ERROR", "operator.email must be a valid email address.")
    if not isinstance(password, str) or not password.strip():
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="Password required.")
        return _err("VALIDATION_ERROR", "operator.password is required and must be a non-empty string.")
    if display_name is not None and not isinstance(display_name, str):
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="Invalid display_name.")
        return _err("VALIDATION_ERROR", "operator.display_name must be a string when provided.")
    if role not in ("owner", "admin", "viewer"):
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="Invalid role.")
        return _err("VALIDATION_ERROR", "operator.role must be one of: owner, admin, viewer.")
    if status not in ("active", "disabled", "locked"):
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="Invalid status.")
        return _err("VALIDATION_ERROR", "operator.status must be one of: active, disabled, locked.")

    # ---- Authenticate via session_token ----
    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    operators = _load("operators.json")
    if not isinstance(operators, list):
        operators = []

    token_hash = _hash_session_token(session_token)
    if token_hash is None:
        _append_log(logs, "error", error_code="VALIDATION_ERROR", message="Invalid session_token.")
        return _err("VALIDATION_ERROR", "session_token must be a non-empty string.")

    # Find a session that matches either:
    # - sessions.session_token_hash == provided "sha256$..." (preferred)
    # - OR sessions.id == provided value (client-visible id fallback)
    # This avoids comparing against unknown plaintext behind stored hashes/ciphertext.
    matching_sessions = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("id") == session_token or s.get("session_token_hash") == token_hash:
            matching_sessions.append(s)

    # Pick a valid session per business rule: active and not expired; if expired, transition to expired.
    valid_session = None
    now_dt = now
    mutated_sessions = False
    for s in matching_sessions:
        st = s.get("status")
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and now_dt >= exp and st == "active":
            s["status"] = "expired"
            s["updated_at"] = now_dt.isoformat()
            mutated_sessions = True
            st = "expired"
        if st == "active" and exp is not None and now_dt < exp:
            valid_session = s
            break

    if mutated_sessions:
        _save("sessions.json", sessions)

    if not valid_session:
        _append_log(logs, "error", error_code="UNAUTHORIZED", message="No valid active session for token/id.")
        return _err("UNAUTHORIZED", "Session is missing, revoked, or expired.")

    session_id = valid_session.get("id")
    actor_operator_id = valid_session.get("operator_id")

    actor = None
    for o in operators:
        if isinstance(o, dict) and o.get("id") == actor_operator_id:
            actor = o
            break

    if not actor:
        _append_log(logs, "error", actor_operator_id=actor_operator_id, session_id=session_id, error_code="UNAUTHORIZED", message="Session operator not found.")
        return _err("UNAUTHORIZED", "Session operator not found.")
    if actor.get("status") != "active":
        _append_log(logs, "error", actor_operator_id=actor_operator_id, session_id=session_id, error_code="UNAUTHORIZED", message="Operator not active.")
        return _err("UNAUTHORIZED", "Operator is not active.")
    if actor.get("role") not in ("owner", "admin"):
        _append_log(logs, "error", actor_operator_id=actor_operator_id, session_id=session_id, error_code="UNAUTHORIZED", message="Insufficient role.")
        return _err("UNAUTHORIZED", "Only owner/admin may create operators.")

    # ---- Enforce uniqueness: unique(email) ----
    email_norm = email.strip().lower()
    for o in operators:
        if not isinstance(o, dict):
            continue
        if isinstance(o.get("email"), str) and o.get("email").strip().lower() == email_norm:
            _append_log(logs, "error", actor_operator_id=actor_operator_id, session_id=session_id, error_code="CONFLICT", message="Email already in use.")
            return _err("CONFLICT", "Email is already in use.", field="email")

    # ---- Create operator ----
    created_at = now.isoformat()
    new_row = {
        "id": _gen_id("mcp_opr"),
        "email": email.strip(),
        # password is accepted only on create/reset; store in password_hash field as provided
        # (real hashing/verification happens in sign-in tool; here we persist what caller provided)
        "password_hash": password,
        "display_name": display_name,
        "role": role,
        "status": status,
        "last_login_at": None,
        "failed_login_count": 0,
        "created_at": created_at,
        "updated_at": created_at
    }

    # constraints: failed_login_count >= 0
    if not isinstance(new_row["failed_login_count"], int) or new_row["failed_login_count"] < 0:
        _append_log(logs, "error", actor_operator_id=actor_operator_id, session_id=session_id, error_code="VALIDATION_ERROR", message="failed_login_count constraint violated.")
        return _err("VALIDATION_ERROR", "failed_login_count must be >= 0.")

    operators.append(new_row)
    _save("operators.json", operators)

    _append_log(logs, "success", actor_operator_id=actor_operator_id, session_id=session_id, message="Operator created.")
    return {"operator": _sanitize_operator_row(new_row)}

def Optional_Settings__update_operator(action, session_token, operator_id, operator, **_extra):
    import json, os, datetime, time, re, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0240000" if __import__("os").path.isdir("./environment_mix/0240000") else "/app/database")
    def _load(n):
