            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _hash_session_token(token):
        presented = token.strip()
        if re.fullmatch(r"[a-fA-F0-9]{64}", presented):
            return presented.lower()
        if presented.startswith("sha256$"):
            maybe = presented.split("$", 1)[1]
            if re.fullmatch(r"[a-fA-F0-9]{64}", maybe):
                return maybe.lower()
        return hashlib.sha256(presented.encode("utf-8")).hexdigest()

    def _log(status, caller_operator_id=None, session_id=None, error_code=None, message=None, target_operator_id=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "mcp_req_" + secrets.token_urlsafe(10),
                "endpoint": "Optional_Settings__update_operator",
                "action": action,
                "status": status,
                "error_code": error_code,
                "message": message,
                "operator_id": caller_operator_id,
                "session_id": session_id,
                "target_operator_id": target_operator_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                "timestamp": _iso(_now()),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if action != "update_operator":
        _log("error", error_code="VALIDATION_ERROR", message="Invalid action")
        return _err("VALIDATION_ERROR", "Invalid action for this endpoint.")
    if not isinstance(session_token, str) or not session_token.strip():
        _log("error", error_code="VALIDATION_ERROR", message="Missing session_token")
        return _err("VALIDATION_ERROR", "session_token must be a non-empty string.")
    if not isinstance(operator_id, str) or not re.match(r"^mcp_opr_[0-9A-HJKMNP-TV-Z]{18,}$", operator_id):
        _log("error", error_code="VALIDATION_ERROR", message="Invalid operator_id")
        return _err("VALIDATION_ERROR", "operator_id must be a valid mcp_opr_ id.")
    if not isinstance(operator, dict) or not operator:
        _log("error", error_code="VALIDATION_ERROR", message="operator patch required")
        return _err("VALIDATION_ERROR", "operator must be a non-empty object.")

    sessions = _load("sessions.json")
    operators = _load("operators.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(operators, list):
        operators = []

    sh = _hash_session_token(session_token)
    sess = None
    for s in sessions:
        if s.get("session_token_hash") == sh:
            sess = s
            break
    if not sess:
        _log("error", error_code="UNAUTHORIZED", message="Session not found")
        return _err("UNAUTHORIZED", "Session not found.")
    now = _now()
    exp = _parse_dt(sess.get("expires_at"))
    if exp and now >= exp and sess.get("status") == "active":
        sess["status"] = "expired"
        sess["updated_at"] = _iso(now)
        sess["last_seen_at"] = _iso(now)
        _save("sessions.json", sessions)
    if sess.get("status") != "active" or (exp and now >= exp):
        _log("error", error_code="UNAUTHORIZED", message="Session invalid", session_id=sess.get("id"))
        return _err("UNAUTHORIZED", "Session is invalid.", session_status=sess.get("status"))

    caller = None
    for o in operators:
        if o.get("id") == sess.get("operator_id"):
            caller = o
            break
    if not caller or caller.get("status") != "active":
        _log("error", error_code="UNAUTHORIZED", message="Operator not active", session_id=sess.get("id"))
        return _err("UNAUTHORIZED", "Operator is not active.")
    if caller.get("role") not in ("owner","admin"):
        _log("error", error_code="UNAUTHORIZED", message="Insufficient role", caller_operator_id=caller.get("id"))
        return _err("UNAUTHORIZED", "Insufficient role to update operators.")

    target = None
    for o in operators:
        if o.get("id") == operator_id:
            target = o
            break
    if not target:
        _log("error", caller_operator_id=caller.get("id"), session_id=sess.get("id"), error_code="NOT_FOUND", message="Target not found", target_operator_id=operator_id)
        return _err("NOT_FOUND", "Operator not found.")

    # apply patch with lifecycle transitions
    allowed_fields = {"display_name","role","status"}
    for k in operator.keys():
        if k not in allowed_fields:
            return _err("VALIDATION_ERROR", f"Field '{k}' cannot be updated.")
    if "role" in operator and operator.get("role") is not None:
        nr = operator.get("role")
        if nr not in ("owner","admin","viewer"):
            return _err("VALIDATION_ERROR", "operator.role is invalid.")
        target["role"] = nr
    if "display_name" in operator:
        dn = operator.get("display_name")
        if dn is not None and (not isinstance(dn, str) or not dn.strip()):
            return _err("VALIDATION_ERROR", "operator.display_name must be a non-empty string when provided.")
        target["display_name"] = dn
    if "status" in operator and operator.get("status") is not None:
        ns = operator.get("status")
        if ns not in ("active","disabled","locked"):
            return _err("VALIDATION_ERROR", "operator.status is invalid.")
        cur = target.get("status")
        transitions = {"active": {"disabled","locked"}, "disabled": {"active"}, "locked": {"active","disabled"}}
        if ns != cur and ns not in transitions.get(cur, set()):
            return _err("INVALID_TRANSITION", f"Cannot transition operator status from {cur} to {ns}.")
        target["status"] = ns
        if ns == "active":
            # unlocking resets failed count per common policy
            try:
                target["failed_login_count"] = int(target.get("failed_login_count") or 0)
            except Exception:
                target["failed_login_count"] = 0

    target["updated_at"] = _iso(_now())
    _save("operators.json", operators)

    # update last_seen
    sess["last_seen_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    _save("sessions.json", sessions)

    out = {k: target.get(k) for k in ("id","email","display_name","role","status","last_login_at","failed_login_count","created_at","updated_at")}
    _log("ok", caller_operator_id=caller.get("id"), session_id=sess.get("id"), target_operator_id=operator_id)
    return {"operator": out}

