            "status": s.get("status"),
            "issued_at": s.get("issued_at"),
            "expires_at": s.get("expires_at"),
            "last_seen_at": s.get("last_seen_at"),
            "created_at": s.get("created_at"),
            "updated_at": s.get("updated_at"),
        })
    _save("sessions.json", sessions)

    desc = sort.startswith("-")
    field = sort[1:] if desc else sort

    def _key(r):
        if field in ("issued_at","expires_at","last_seen_at","created_at"):
            return _parse_dt(r.get(field)) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        v = r.get(field)
        return "" if v is None else str(v).lower()

    rows.sort(key=_key, reverse=desc)

    start = 0
    if cursor:
        cobj = _decode_cursor(cursor)
        if cobj and cobj.get("after"):
            after = cobj["after"]
            for i, r in enumerate(rows):
                if r.get("id") == after:
                    start = i + 1
                    break

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = _encode_cursor({"after": page[-1]["id"]}) if has_more and page else None

    _log("ok", caller_operator_id=caller.get("id"), session_id=sess.get("id"))
    return {"items": page, "total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "sort": sort}

def Optional_Settings__whoami(action, session_token, **_extra):
    import json, os, datetime, time, re, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0240000" if __import__("os").path.isdir("./environment_mix/0240000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _hash_session_token(token):
        presented = token.strip()
        if re.fullmatch(r"[a-fA-F0-9]{64}", presented):
            return presented.lower()
        if presented.startswith("sha256$"):
            maybe = presented.split("$", 1)[1]
            if re.fullmatch(r"[a-fA-F0-9]{64}", maybe):
                return maybe.lower()
        return hashlib.sha256(presented.encode("utf-8")).hexdigest()

    def _log(status, operator_id=None, session_id=None, error_code=None, message=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "mcp_req_" + secrets.token_urlsafe(10),
                "endpoint": "Optional_Settings__whoami",
                "action": action,
                "status": status,
                "error_code": error_code,
                "message": message,
                "operator_id": operator_id,
                "session_id": session_id,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                "timestamp": _iso(_now()),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_info():
        # Use request_logs.json to compute last 60s count; limit 120/min.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return {"limit_per_minute": 120, "used_last_minute": 0, "remaining_last_minute": 120}
        now = _now()
        cutoff = now - datetime.timedelta(seconds=60)
        used = 0
        for r in logs[-2000:]:
            ts = _parse_dt(r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                used += 1
        rem = max(0, 120 - used)
        return {"limit_per_minute": 120, "used_last_minute": used, "remaining_last_minute": rem}

    if action != "whoami":
        _log("error", error_code="VALIDATION_ERROR", message="Invalid action")
        return _err("VALIDATION_ERROR", "Invalid action for this endpoint.")
    if not isinstance(session_token, str) or not session_token.strip():
        _log("error", error_code="VALIDATION_ERROR", message="Missing session_token")
        return _err("VALIDATION_ERROR", "session_token must be a non-empty string.")

    sessions = _load("sessions.json")
    operators = _load("operators.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(operators, list):
        operators = []

    now = _now()
    sh = _hash_session_token(session_token)
    sess = None
    for s in sessions:
        if s.get("session_token_hash") == sh:
            sess = s
            break
    if not sess:
        _log("error", error_code="UNAUTHORIZED", message="Session not found")
        return _err("UNAUTHORIZED", "Session not found.")

    exp = _parse_dt(sess.get("expires_at"))
    if exp and now >= exp and sess.get("status") == "active":
        sess["status"] = "expired"
        sess["updated_at"] = _iso(now)
        sess["last_seen_at"] = _iso(now)
        _save("sessions.json", sessions)

    if sess.get("status") != "active":
        _log("error", session_id=sess.get("id"), operator_id=sess.get("operator_id"), error_code="UNAUTHORIZED", message="Session not active")
        return _err("UNAUTHORIZED", "Session is not active.", session_status=sess.get("status"))
    if exp and now >= exp:
        _log("error", session_id=sess.get("id"), operator_id=sess.get("operator_id"), error_code="UNAUTHORIZED", message="Session expired")
        return _err("UNAUTHORIZED", "Session expired.")

    op = None
    for o in operators:
        if o.get("id") == sess.get("operator_id"):
            op = o
            break
    if not op:
        _log("error", session_id=sess.get("id"), error_code="UNAUTHORIZED", message="Operator not found")
        return _err("UNAUTHORIZED", "Operator not found.")
    if op.get("status") != "active":
        _log("error", session_id=sess.get("id"), operator_id=op.get("id"), error_code="UNAUTHORIZED", message="Operator not active")
        return _err("UNAUTHORIZED", "Operator is not active.", operator_status=op.get("status"))

    # update last_seen
    sess["last_seen_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    _save("sessions.json", sessions)

    scopes = ["read"]
    if op.get("role") in ("owner","admin"):
        scopes += ["operators:write", "servers:write", "credentials:write"]
    else:
        scopes += ["operators:read", "servers:read", "credentials:read"]

    out = {
        "operator": {
            "id": op.get("id"),
            "email": op.get("email"),
            "display_name": op.get("display_name"),
            "role": op.get("role"),
            "status": op.get("status"),
        },
        "session": {
            "id": sess.get("id"),
            "status": sess.get("status"),
            "issued_at": sess.get("issued_at"),
            "expires_at": sess.get("expires_at"),
            "last_seen_at": sess.get("last_seen_at"),
        },
        "scopes": scopes,
        "rate_limit": _rate_info(),
    }

    _log("ok", operator_id=op.get("id"), session_id=sess.get("id"))
    return out
